import {clamp,R} from './physics.js?v=18-29';
export const distance=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
export function laneClearance(from,to,defenders){const dx=to.x-from.x,dz=to.z-from.z,ll=dx*dx+dz*dz;return defenders.reduce((best,d)=>{const u=((d.x-from.x)*dx+(d.z-from.z)*dz)/(ll||1);if(u<.08||u>.96)return best;return Math.min(best,Math.hypot(d.x-from.x-u*dx,d.z-from.z-u*dz));},20);}
export function canShoot(p,defenders){return p.z< -9&&Math.abs(p.x)<8&&distance(p,{x:0,z:-20})<13&&[-2.7,0,2.7].some(x=>laneClearance(p,{x,z:-20},defenders)>.38);}
export function teamDecision(carrier,partners,defenders,keeper,preferred=null){
 // 13 · personalities: a winger takes players on, a playmaker looks for the pass, a forward attacks the box.
 const style=carrier.style||'';if(style==='ailier'&&Math.min(20,...defenders.map(d=>distance(d,carrier)))>1.8&&carrier.z>-15){const t={x:clamp(carrier.x*.85,-13,13),z:Math.max(-17,carrier.z-4.5)};if(laneClearance(carrier,t,defenders)>.9)return {kind:'carry',target:t};}
 if(canShoot(carrier,defenders)){const targets=[-2.8,2.8,0].map(x=>({x,z:-21}));targets.sort((a,b)=>(laneClearance(carrier,b,defenders)*2+Math.abs(b.x-keeper.x))-(laneClearance(carrier,a,defenders)*2+Math.abs(a.x-keeper.x)));return {kind:'shot',target:targets[0]};}
 const central=partners.filter(p=>p!==carrier&&p.z<-10&&Math.abs(p.x)<5).sort((a,b)=>a.z-b.z)[0];
 if(Math.abs(carrier.x)>8&&carrier.z<-7&&central&&laneClearance(carrier,central,defenders)<1.4)return {kind:'cross',receiver:central,target:{x:central.x,z:central.z}};
 const forward={x:clamp(carrier.x*.92,-13,13),z:Math.max(-18,carrier.z-4)},pressure=Math.min(20,...defenders.map(d=>distance(d,carrier)));
 const candidates=partners.filter(p=>p!==carrier&&distance(p,carrier)>2&&distance(p,carrier)<30).map(p=>{const lane=laneClearance(carrier,p,defenders),space=Math.min(8,...defenders.map(d=>distance(d,p))),progress=carrier.z-p.z;return {p,lane,score:Math.min(lane,4)*.7+space*.35+progress*.45-distance(p,carrier)*.07+(canShoot(p,defenders)?4:0)+(p===preferred?2.2:0)-(p===carrier.lastPasser?3:0)-(progress< -3?3:0)};}).filter(c=>c.lane>.75);
 candidates.sort((a,b)=>b.score-a.score);
 // Carry into free space before passing sideways; a forward run by the player is preferred.
 if(pressure>2.6&&laneClearance(carrier,forward,defenders)>1.1&&(!candidates.length||candidates[0].score<(style==='meneur'?4.5:6.5)))return {kind:'carry',target:forward};
 if(candidates.length)return {kind:'pass',receiver:candidates[0].p,target:{x:candidates[0].p.x,z:candidates[0].p.z}};
 return {kind:'carry',target:{x:clamp(carrier.x+(carrier.x<0?-1:1)*1.2,-13,13),z:Math.max(-16,carrier.z-1.8)}};
}
// Stable one-to-one marking persists for the whole touch, avoiding target oscillation.
export function assignMarkers(defenders,carrier,partners){const available=new Set(partners.filter(p=>p!==carrier));let primary=-1,best=Infinity;defenders.forEach((d,i)=>{const v=distance(d,carrier);if(v<best){best=v;primary=i;}});defenders.forEach((d,i)=>{d.mark=null;if(i===primary)return;let choice=null,score=Infinity;for(const p of available){const v=distance(d,p)+Math.max(0,p.z-d.z)*.15;if(v<score){score=v;choice=p;}}if(choice){d.mark=choice;available.delete(choice);}});return primary;}
export function defensiveTarget(d,carrier,ball,primary,flying,intent){if(primary){if(flying){const t=clamp(distance(d,ball)/20,.04,.3);return {x:clamp(ball.x+(ball.vx||0)*t,-15,15),z:clamp(ball.z+(ball.vz||0)*t,-19,30)};}const dx=intent.x-carrier.x,dz=intent.z-carrier.z,len=Math.hypot(dx,dz);if(len<.05)return {x:carrier.x+(carrier.vx||0)*.15,z:carrier.z-1.4};const ahead=Math.min(len,2.4);/* meet the carrier where the touch is going, from the goal side */return {x:carrier.x+dx/len*ahead+(carrier.vx||0)*.15,z:carrier.z+dz/len*ahead+(carrier.vz||0)*.15-.45};}if(d.cover){return {x:clamp(carrier.x*.75,-12,12),z:Math.max(-19,carrier.z-2.5)};}if(d.mark){const p=d.mark,dx=ball.x-p.x,dz=ball.z-p.z,len=Math.hypot(dx,dz)||1;return {x:p.x+dx/len*1.15,z:Math.min(p.z+dz/len*1.15,carrier.z-.8)};}return {x:clamp(carrier.x*.4+d.home.x*.6,-14,14),z:Math.max(-18,carrier.z-3)};}
// Relative swept collision: a fast ball cannot jump through a moving receiver.
export function sweptPlayerContact(before,after,p,radius=.65,height=1.55){const old=p.previous||p;const sx=before.x-old.x,sz=before.z-old.z,dx=(after.x-p.x)-sx,dz=(after.z-p.z)-sz,rr=radius+R;const aa=dx*dx+dz*dz,bb=2*(sx*dx+sz*dz),cc=sx*sx+sz*sz-rr*rr;let t=0;if(cc>0){const disc=bb*bb-4*aa*cc;if(aa<1e-12||disc<0)return null;t=(-bb-Math.sqrt(disc))/(2*aa);if(t<0||t>1)return null;}const y=before.y+(after.y-before.y)*t;if(y>height+R)return null;return {t,x:before.x+(after.x-before.x)*t,z:before.z+(after.z-before.z)*t,y};}

export function refreshDefence(defenders,carrier,partners,current=-1){if(!defenders.length)return -1;const score=d=>distance(d,carrier)+(d.z>carrier.z+.5?2.3:0)+(d.challenge?2:0);let selected=defenders.reduce((best,d,i)=>score(d)<score(defenders[best])?i:best,0);if(current>=0&&defenders[current]&&score(defenders[current])<score(defenders[selected])+.4)selected=current;for(const d of defenders)d.cover=false;const choices=defenders.filter((d,i)=>i!==selected&&d.z<carrier.z+.5).sort((a,b)=>distance(a,carrier)-distance(b,carrier));if(choices[0])choices[0].cover=true;const used=new Set();for(const [i,d] of defenders.entries()){if(i===selected||d.cover){d.mark=null;continue;}const candidates=partners.filter(p=>p!==carrier&&!used.has(p)).sort((a,b)=>distance(d,a)-distance(d,b));d.mark=candidates[0]||null;if(d.mark)used.add(d.mark);}return selected;}
